// Extract incoming payload safely
const raw = $input.first().json;
const body = (raw && raw.body) ? raw.body : raw;
const rawPhone = String((body && (body.phone || body.from || (body.message && body.message.from ? body.message.from.id : null))) || '9829012345');
const text = String((body && (body.text || body.message_text || (body.message ? body.message.text : '') || body.description)) || '');

// Location stays null when the resident sent no GPS pin. Do NOT substitute a city-centre
// default -- that invents a location the citizen never reported and pins every locationless
// message to the same zone. The API rejects a report with no location, and node 7 tells the
// resident to resend with one.
let lat = null;
let lon = null;
if (body && body.message && body.message.location) {
  // Real Telegram GPS attachment pin
  lat = Number(body.message.location.latitude);
  lon = Number(body.message.location.longitude);
} else if (body && body.lat != null && body.lon != null) {
  // Real coordinates passed via payload
  lat = Number(body.lat);
  lon = Number(body.lon);
}

const channel = (body && (body.channel || (body.message ? 'telegram' : 'whatsapp'))) || 'whatsapp';
const chatId = (body && body.message && body.message.chat) ? body.message.chat.id : null;

// Pure-JS SHA-256. Used only when require('crypto') is unavailable, which is the case on
// some n8n Cloud plans -- that restriction is why this node previously shipped a 32-bit
// loop hash with 24 constant characters glued on to look like a digest.
function sha256Hex(ascii) {
  function rr(n, x) { return (x >>> n) | (x << (32 - n)); }
  const K = [];
  const H = [];
  let p = 2, i = 0;
  while (i < 64) {
    let isPrime = true;
    for (let f = 2; f * f <= p; f++) if (p % f === 0) { isPrime = false; break; }
    if (isPrime) {
      const c = Math.pow(p, 1 / 3);
      K[i] = ((c - Math.floor(c)) * Math.pow(2, 32)) | 0;
      if (i < 8) { const s = Math.pow(p, 1 / 2); H[i] = ((s - Math.floor(s)) * Math.pow(2, 32)) | 0; }
      i++;
    }
    p++;
  }
  // UTF-8 encode
  const bytes = [];
  for (let j = 0; j < ascii.length; j++) {
    let c = ascii.charCodeAt(j);
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) { bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63)); }
    else if (c < 0xd800 || c >= 0xe000) { bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63)); }
    else { j++; c = 0x10000 + (((c & 0x3ff) << 10) | (ascii.charCodeAt(j) & 0x3ff));
           bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63)); }
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 4294967296), lo = bitLen >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255,
             (lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  const w = new Array(64);
  for (let b = 0; b < bytes.length; b += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = (bytes[b + t * 4] << 24) | (bytes[b + t * 4 + 1] << 16) | (bytes[b + t * 4 + 2] << 8) | bytes[b + t * 4 + 3];
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rr(7, w[t - 15]) ^ rr(18, w[t - 15]) ^ (w[t - 15] >>> 3);
      const s1 = rr(17, w[t - 2]) ^ rr(19, w[t - 2]) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
    }
    let [a, bb, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rr(6, e) ^ rr(11, e) ^ rr(25, e);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + w[t]) | 0;
      const S0 = rr(2, a) ^ rr(13, a) ^ rr(22, a);
      const mj = (a & bb) ^ (a & c) ^ (bb & c);
      const t2 = (S0 + mj) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = bb; bb = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + bb) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map(x => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

// Salted phone hash (privacy). This node is named SHA-256 and must actually be SHA-256:
// a previous version used a 32-bit loop hash with 24 constant characters appended to look
// like a digest, which is reversible for a 10-digit number and collides into the 6-hour
// deduplicator, silently marking distinct reporters as duplicates of each other.
let cleanDigits = rawPhone.replace(/\D/g, '') || '9829012345';
if (cleanDigits.length === 12 && cleanDigits.startsWith('91')) { cleanDigits = cleanDigits.substring(2); }
else if (cleanDigits.length === 11 && cleanDigits.startsWith('0')) { cleanDigits = cleanDigits.substring(1); }

// n8n Cloud forces N8N_BLOCK_ENV_ACCESS_IN_NODE=true, so $env throws in a Code node here.
// $vars is the Cloud replacement but only exists on some plans -- read it defensively.
// Keep this fallback in step with utils/hasher.py on the Python side.
let phoneSalt = 'neerdrishti-default-salt-2026';
try {
  if (typeof $vars !== 'undefined' && $vars && $vars.PHONE_SALT) { phoneSalt = $vars.PHONE_SALT; }
} catch (e) { /* Variables not available on this plan -- keep the fallback */ }

const saltStr = cleanDigits + ':' + phoneSalt;
// require('crypto') is blocked on some n8n Cloud plans, so fall back to the pure-JS
// implementation above. Both produce identical digests -- verified against hashlib.
let hexHash;
try {
  hexHash = require('crypto').createHash('sha256').update(saltStr).digest('hex');
} catch (e) {
  hexHash = sha256Hex(saltStr);
}
const reporterHash = 'sha256:' + hexHash.substring(0, 32);

// Detect Language Script
let detectedLang = 'en';
let sarvamCode = 'hi-IN';
if (/[\u0900-\u097F]/.test(text)) { detectedLang = 'hi'; sarvamCode = 'hi-IN'; }
else if (/[\u0B80-\u0BFF]/.test(text)) { detectedLang = 'ta'; sarvamCode = 'ta-IN'; }
else if (/[\u0C80-\u0CFF]/.test(text)) { detectedLang = 'kn'; sarvamCode = 'kn-IN'; }
else if (/[\u0C00-\u0C7F]/.test(text)) { detectedLang = 'te'; sarvamCode = 'te-IN'; }
else if (/[\u0D00-\u0D7F]/.test(text)) { detectedLang = 'ml'; sarvamCode = 'ml-IN'; }
else if (/[\u0A80-\u0AFF]/.test(text)) { detectedLang = 'gu'; sarvamCode = 'gu-IN'; }
else if (/[\u0980-\u09FF]/.test(text)) { detectedLang = 'bn'; sarvamCode = 'bn-IN'; }

return [{
  json: {
    channel,
    chat_id: chatId,
    reporter_hash: reporterHash,
    incoming_text: text,
    detected_language: detectedLang,
    sarvam_language_code: sarvamCode,
    is_regional: detectedLang !== 'en',
    lat,
    lon
  }
}];

// Standardize description using Sarvam AI result or Domain Fallback Dictionary
const prev = $('2. Extract & Hash Phone (SHA-256)').first().json;
let englishText = prev.incoming_text;

try {
  const apiRes = $input.first().json;
  if (apiRes && apiRes.translated_text) {
    englishText = apiRes.translated_text;
  } else {
    throw new Error('Using dictionary fallback');
  }
} catch (err) {
  const dict = {
    'पानी बह रहा है': 'water is flowing',
    'पानी लीक हो रहा है': 'water is leaking',
    'पाइप टूट गया': 'pipe is broken',
    'सड़क पर पानी': 'water on the road',
    'स्कूल के पास': 'near the school',
    'தண்ணீர் கசிகிறது': 'water is leaking',
    'ನೀರು ಸೋರುತ್ತಿದೆ': 'water is leaking'
  };
  for (const [k, v] of Object.entries(dict)) {
    if (englishText.includes(k)) englishText = englishText.replace(k, v);
  }
  if (englishText === prev.incoming_text && prev.is_regional) {
    englishText = '[Citizen Leak Report in ' + prev.detected_language.toUpperCase() + ']: ' + prev.incoming_text;
  }
}

return [{
  json: {
    ...prev,
    description: englishText
  }
}];

const raw = $('1. WhatsApp / Telegram Webhook').first().json;
const body = raw.body || raw;

// Extract exact Telegram Chat ID
const chatId = (body.message && body.message.chat) ? body.message.chat.id :
               (body.chat_id || (body.message && body.message.from ? body.message.from.id : null));

const lang = $('2. Extract & Hash Phone (SHA-256)').first().json.detected_language || 'en';
const src = $('5. Format Standardized Description').first().json;
const desc = src.description;

// Node 6 runs with onError: continueRegularOutput, so a rejected POST still reaches this
// node. Without this check the resident is told their leak was logged when nothing was
// stored at all -- the API returns 422 for a report with no location, and the old receipt
// answered that with a green tick and an invented ticket number.
const api = $('6. Ingest into NeerDrishti API').first().json;
const stored = Number.isInteger(api.id);
// Decide *why* it failed from what the API actually said, not from what we assume node 5
// holds. The 422 body is: "provide zone_id, or both lat and lon". Falling back to the
// lat/lon check alone got this wrong in testing.
const apiSaid = JSON.stringify(api.detail || api.message || api.error || '');
const blamesLocation = /zone_id|\blat\b|\blon\b|location/i.test(apiSaid);
const hasLocation = Number.isFinite(Number(src.lat)) && Number.isFinite(Number(src.lon))
                    && src.lat !== null && src.lon !== null;
const missingLocation = blamesLocation || !hasLocation;
const scored = stored && api.status === 'new';
const zoneLabel = stored ? (api.zone_id || 'outside the mapped municipal zones') : null;

let message;
if (!stored && missingLocation) {
  // The common case: a description typed with no GPS attachment.
  message = lang === 'hi'
    ? `💧 नीरदृष्टि स्मार्ट जल खुफिया प्रणाली\n\n` +
      `⚠️ रिपोर्ट दर्ज नहीं हुई — स्थान नहीं मिला\n` +
      `📝 आपका संदेश: ${desc}\n\n` +
      `कृपया वही विवरण दोबारा भेजें और साथ में अपना GPS स्थान संलग्न करें ` +
      `(📎 → Location)। स्थान के बिना हम रिसाव को किसी वार्ड से नहीं जोड़ सकते।`
    : `💧 NeerDrishti Smart Water Intelligence\n\n` +
      `⚠️ Not logged — no location received\n` +
      `📝 Your message: ${desc}\n\n` +
      `Please send the same description again with your GPS location attached ` +
      `(📎 → Location). Without it we cannot match the leak to a ward.`;
} else if (!stored) {
  // Location was present, so this is an API or network failure, not the resident's doing.
  message = lang === 'hi'
    ? `💧 नीरदृष्टि स्मार्ट जल खुफिया प्रणाली\n\n` +
      `⚠️ रिपोर्ट दर्ज नहीं हो सकी — तकनीकी समस्या\n` +
      `📝 आपका संदेश: ${desc}\n\n` +
      `आपकी गलती नहीं है। कृपया कुछ मिनट बाद दोबारा भेजें।`
    : `💧 NeerDrishti Smart Water Intelligence\n\n` +
      `⚠️ Could not log this report — technical problem\n` +
      `📝 Your message: ${desc}\n\n` +
      `Nothing you did wrong. Please send it again in a few minutes.`;
} else {
  message = lang === 'hi'
    ? `💧 नीरदृष्टि स्मार्ट जल खुफिया प्रणाली\n\n` +
      `${scored ? '✅ जल रिसाव रिपोर्ट दर्ज की गई' : '⚠️ संदेश दर्ज किया गया'}\n` +
      `📍 जोन: ${zoneLabel}\n` +
      `📝 विवरण: ${desc}\n` +
      `🆔 टिकट संदर्भ: #${api.id}\n` +
      `⏳ स्थिति: ${scored ? 'वार्ड समीक्षा के लिए दर्ज।' : 'इसे रिसाव रिपोर्ट के रूप में नहीं पढ़ा गया — कृपया समस्या का विवरण भेजें।'}`
    : `💧 NeerDrishti Smart Water Intelligence\n\n` +
      `${scored ? '✅ Water Leak Report Logged' : '⚠️ Message Recorded'}\n` +
      `📍 Matched Zone: ${zoneLabel}\n` +
      `📝 Description: ${desc}\n` +
      `🆔 Ticket Ref: #${api.id}\n` +
      `⏳ Status: ${scored ? 'Queued for ward review.' : 'Not read as a leak report -- reply describing the problem and we will log it.'}`;
}

return [{
  json: {
    status: stored ? 'success' : 'not_stored',
    chat_id: chatId,
    ticket_id: stored ? api.id : null,
    zone_id: stored ? (api.zone_id || null) : null,
    receipt_message: message
  }
}];

parameters.jsonBody:
={
  "chat_id": "{{ $json.chat_id }}",
  "text": "Welcome to NeerDrishti! 💧\n\nTo report a water leak, please send a short description of the problem and your GPS location (attachment).",
  "parse_mode": "Markdown"
}
